//! Native PowerShell 7.7.0 argument boundaries and protected whitespace.

use super::powershell::{call, run_clean};

const HORIZONTAL_SPACES: &[char] = &['\u{9}', '\u{b}', '\u{c}', '\u{20}', '\u{85}', '\u{a0}', '\u{1680}', '\u{2000}', '\u{2001}', '\u{2002}', '\u{2003}', '\u{2004}', '\u{2005}', '\u{2006}', '\u{2007}', '\u{2008}', '\u{2009}', '\u{200a}', '\u{2028}', '\u{2029}', '\u{202f}', '\u{205f}', '\u{3000}'];

#[test]
fn unicode_horizontal_spaces_preserve_native_argument_counts() {
    for &space in HORIZONTAL_SPACES {
        for (kind, source, count) in [
            ("after-command", format!("Capture-Native{space}hello world\n"), 2),
            ("between-arguments", format!("Capture-Native hello{space}world\n"), 2),
            ("before-double-dash", format!("Capture-Native hello{space}-- world\n"), 3),
            ("after-double-dash", format!("Capture-Native hello --{space}world\n"), 3),
            ("before-single-dash", format!("Capture-Native hello{space}- world\n"), 3),
            ("after-single-dash", format!("Capture-Native hello -{space}world\n"), 3),
        ] {
            let analysis = run_clean(&source);
            let actual = call(&analysis, "Capture-Native").args.len();
            assert_eq!(actual, count, "{kind}, U+{:04X}: {source:?}", u32::from(space));
            println!("NATIVE_ARGUMENT_CASE space-{:04x}-{kind} {actual}", u32::from(space));
        }
    }
}

#[test]
fn protected_spaces_and_format_marks_stay_inside_native_arguments() {
    for &space in HORIZONTAL_SPACES {
        for (kind, source) in [
            ("quoted", format!("Capture-Native \"hello{space}world\"\n")),
            ("escaped", format!("Capture-Native hello`{space}world\n")),
        ] {
            let analysis = run_clean(&source);
            let actual = call(&analysis, "Capture-Native").args.len();
            assert_eq!(actual, 1, "{kind}, U+{:04X}: {source:?}", u32::from(space));
            println!("NATIVE_ARGUMENT_CASE space-{:04x}-{kind} {actual}", u32::from(space));
        }
    }
    for mark in ['\u{feff}', '\u{200b}', '\u{2060}'] {
        for (kind, source) in [
            ("word", format!("Capture-Native hello{mark}world\n")),
            ("dash", format!("Capture-Native --{mark}tail\n")),
        ] {
            let analysis = run_clean(&source);
            let actual = call(&analysis, "Capture-Native").args.len();
            assert_eq!(actual, 1, "{kind}, U+{:04X}: {source:?}", u32::from(mark));
            println!("NATIVE_ARGUMENT_CASE format-{:04x}-{kind} {actual}", u32::from(mark));
        }
    }
}

//! Plain command-word Unicode escapes retain Str shape without counting spelling.

use sloplint_core::facts::ArgShape;

use super::powershell::{call, run_clean};

#[test]
fn unicode_escape_spelling_does_not_lengthen_plain_literal_runs() {
    for (name, source, expected) in [
        ("plain-bare-short", "Write-Host `u{000041}x\n", 1),
        ("plain-bare-long", "Write-Host `u{000041}abcdefgh\n", 8),
        ("plain-bare-prefix-near", "Write-Host abcdefg`u{000041}x\n", 7),
        ("plain-bare-prefix-long", "Write-Host abcdefgh`u{000041}x\n", 8),
        ("plain-bare-scalar", "Write-Host `u{1F600}x\n", 1),
        ("plain-bare-short-hex", "Write-Host `u{41}x\n", 1),
        ("plain-mixed-expandable", "Write-Host p\"`u{000041}x\"\n", 1),
        ("plain-verbatim-and-escape", "Write-Host p'`u{000041}'`u{42}x\n", 11),
    ] {
        let analysis = run_clean(source);
        let command = call(&analysis, "Write-Host");
        assert_eq!(command.args.len(), 1, "{name}");
        let ArgShape::Str { longest_static } = command.args[0].shape else {
            panic!("{name}: expected Str, got {:?}", command.args[0].shape);
        };
        assert_eq!(longest_static, expected, "{name}: {source:?}");
    }
}

#[test]
fn unaffected_plain_word_measurements_keep_their_existing_contract() {
    for (name, source, expected) in [
        ("plain-mixed-verbatim", "Write-Host p'`u{000041}x'\n", 14),
        ("plain-uppercase-ordinary", "Write-Host p\"`U{000041}x\"\n", 14),
        ("plain-plain", "Write-Host hello\n", 5),
        ("plain-ordinary-space", "Write-Host hello` world\n", 12),
        ("plain-ordinary-dollar", "Write-Host v`$VERSION.tar.gz\n", 17),
    ] {
        let analysis = run_clean(source);
        let command = call(&analysis, "Write-Host");
        assert_eq!(command.args.len(), 1, "{name}");
        let ArgShape::Str { longest_static } = command.args[0].shape else {
            panic!("{name}: expected Str, got {:?}", command.args[0].shape);
        };
        assert_eq!(longest_static, expected, "{name}: {source:?}");
    }
}
